# November 22, 2026: the Bronx, the first places there (region nyc drawn at random by choose.py --state ny;
# tools/start.py found no Atlas place within 4 km of the borough's middle, and only Fort Totten and the 1964 pavilion
# in Queens within 12 km).
# Facts come only from sources opened in this session: Wikipedia read as raw text (tools/wiki_raw.py), the Historic House
# Trust's house pages, NYC Parks pages (Seton Park history, the Van Cortlandt Park railroad article of 2006, North Brother
# Island), the New York Botanical Garden, Wave Hill, Woodlawn Cemetery, SUNY Maritime College, Bronx Community College,
# Grace Church City Island, the Riverdale Press (Seton Park grotto, 2021), Welcome2TheBronx (courthouse sale, 2024),
# the Governor's office (Kingsbridge Armory plan, October 2025) and Forgotten New York (the Putnam Trail).
from data_b import N
from data_ma import W
def L(t,u): return [t,u]
HHT=lambda slug,t: ['Historic House Trust: '+t,'https://historichousetrust.org/houses/'+slug+'/']

BATCH={'key':'nyc_kvbt','label':'The Bronx','added':'2026-11-22 15:02'}

PLACES=[
N('van-cortlandt-house-bronx','Van Cortlandt House Museum','Bronx (Van Cortlandt Park)','nyc','landmark','standing',40.89114,-73.89483,'exact','open','walk','','1748–1749',
  'The oldest known house in the Bronx: a Georgian rubblestone house that Frederick Van Cortlandt began in 1748 on the family\'s wheat farm and that was finished in 1749 after his death. British and American troops both used it during the Revolution. The city bought it in 1888 for Van Cortlandt Park and used it as a police barracks; the Colonial Dames of the State of New York opened it as a museum in 1897.',
  'An L-shaped stone house with red-brick frames round the windows and carved keystones showing the faces of family members. Inside, the Colonial Dames have furnished the rooms to show the house as it may have looked between 1749 and 1823: two parlors, an entry hall and a dining room on the first floor and a basement kitchen with a Dutch brick oven set in its wall. Open to visitors Wednesday to Sunday.',
  'The Bronx\'s oldest house, still sitting in a park of farm fields turned ball fields.',
  'Owned by NYC Parks and run by the National Society of Colonial Dames in the State of New York (Historic House Trust page). Entrance from Broadway near West 246th Street; the mapped park lot on Van Cortlandt Avenue West is about 300 m south-east. Hours from the Historic House Trust page.',
  [W('Van Cortlandt House'),HHT('van-cortlandt-house-museum','Van Cortlandt House Museum')],
  th=[40.88849,-73.89345],thn='Van Cortlandt Park lot, Van Cortlandt Avenue West',brick='some',
  hours='Wednesday to Sunday 11 a.m. to 4 p.m. (last entry 3:30)'),

N('valentine-varian-house-bronx','Valentine–Varian House (Museum of Bronx History)','Bronx (Norwood)','nyc','landmark','standing',40.87739,-73.87944,'exact','open','walk','','1758',
  'A two-story fieldstone farmhouse built in 1758 by Isaac Valentine, a blacksmith and farmer: the second oldest house in the Bronx and its oldest farmhouse. Hessian, British and American troops all occupied it in the Revolution. The Varian family farmed here for three generations until 1905. It was moved to its present spot in 1965 and restored by 1968, and the Bronx County Historical Society runs it as the Museum of Bronx History.',
  'A five-bay fieldstone house with a gable roof in a small park on Bainbridge Avenue. Inside is the Museum of Bronx History; interior fabric not checked. Open Saturdays.',
  '',
  'Owned by NYC Parks and run by the Bronx County Historical Society (Historic House Trust page). Street parking only; no mapped lot was found close by. Hours from the Historic House Trust page.',
  [W('Valentine–Varian House'),HHT('valentine-varian-house','Valentine–Varian House')],
  brick='no',hours='Saturday 10 a.m. to 4 p.m.'),

N('poe-cottage-bronx','Edgar Allan Poe Cottage','Bronx (Fordham)','nyc','landmark','standing',40.86528,-73.89444,'site','open','walk','','c. 1797; Poe lived here 1846–1849',
  'A small farm cottage, thought to date from 1797, that Edgar Allan Poe rented from 1846 with his wife Virginia and her mother. Virginia died in its first-floor bedroom in January 1847, and Poe stayed on until 1849, the year he died. It was moved a short way in 1913 to the north end of Poe Park, and the Bronx County Historical Society has run it since 1975.',
  'A tiny white cottage in Poe Park near Kingsbridge Road and the Grand Concourse. The rooms are furnished as in the 1840s, with a desk, a rope bed and a wicker rocking chair thought to have belonged to the family (Historic House Trust page). Open weekends.',
  'Where Poe wrote after Virginia died, now hemmed in by the Grand Concourse.',
  'Owned by NYC Parks and run by the Bronx County Historical Society (Historic House Trust page, which also says tours are by appointment). Street parking; the Kingsbridge Road subway stations are close by. Hours from the Historic House Trust page.',
  [W('Edgar Allan Poe Cottage'),HHT('edgar-allan-poe-cottage','Edgar Allan Poe Cottage')],
  brick='?',hours='Saturday 10 a.m. to 4 p.m.; Sunday 1 to 5 p.m.'),

N('bartow-pell-mansion-bronx','Bartow–Pell Mansion','Bronx (Pelham Bay Park)','nyc','landmark','standing',40.87194,-73.80556,'site','open','walk','','1836–1842',
  'The last of the manor houses in what is now Pelham Bay Park. Thomas Pell bought the land from the Siwanoy in 1654; Robert Bartow, a relative, built the present house with its Greek Revival front between 1836 and 1842. The city bought it in 1888; the International Garden Club restored it as its clubhouse from 1914, Mayor La Guardia spent the summer of 1936 here, and it opened as a museum in 1946.',
  'A two-story house with a three-story carriage house, terraced gardens looking out to Long Island Sound and a small Pell family burial plot, on 9 acres. The interiors are restored to their 19th-century look, with furniture by New York cabinetmakers (Historic House Trust page); room by room not checked. Room inside is limited during open hours.',
  '',
  'Owned by NYC Parks and run by the Bartow-Pell Conservancy (Historic House Trust page). On Shore Road in the north of Pelham Bay Park; the mapped park lot off Shore Road by the Siwanoy Trail is about 400 m west. Hours from the Historic House Trust page.',
  [W('Bartow–Pell Mansion'),HHT('bartow-pell-mansion-museum','Bartow-Pell Mansion Museum')],
  th=[40.87234,-73.81018],thn='Pelham Bay Park lot near the Siwanoy Trail, Shore Road',brick='?',
  hours='Wednesday, Saturday and Sunday noon to 4 p.m.'),

N('fort-schuyler-bronx','Fort Schuyler (Maritime Industry Museum)','Bronx (Throggs Neck)','nyc','fort','standing',40.80556,-73.79194,'site','open','drive','','1833–1856',
  'A Third System coastal fort at the tip of Throggs Neck, begun in 1833 and dedicated in 1856 when about three-quarters finished, to guard the Long Island Sound end of New York Harbor with Fort Totten across the water. It was garrisoned from 1861, disarmed in 1934 and handed to the state, rebuilt by the Works Progress Administration and given to the state\'s maritime school in 1938.',
  'The fort walls with two tiers of casemates and gun positions on the roof. Inside are the Maritime Industry Museum, the college library and offices. Open to visitors Monday to Saturday; admission and parking are free (SUNY Maritime page).',
  'Fort Totten\'s finished twin, now a college.',
  'SUNY Maritime College campus. Enter at the college gate and follow Erben Avenue under the Throggs Neck Bridge approach, then the signs for museum parking (SUNY Maritime page). Guided tours can be arranged with the museum office. Hours from the SUNY Maritime page.',
  [W('Fort Schuyler'),L('SUNY Maritime: museum hours and directions','https://www.sunymaritime.edu/node/8782')],
  th=[40.80651,-73.79222],thn='Erben Avenue lot, SUNY Maritime',brick='?',
  hours='Monday to Saturday 9 a.m. to 4 p.m.'),

N('lorillard-snuff-mill-bronx','Lorillard Snuff Mill (Stone Mill)','Bronx (New York Botanical Garden)','nyc','industry','standing',40.85968,-73.87617,'exact','open','walk','','c. 1840',
  'The oldest tobacco factory building left in the United States, built about 1840 of local schist beside the Bronx River for the Lorillard snuff firm, which had moved its grinding here in 1792. The company left for Jersey City in 1870. The city bought the land in 1884, and the mill passed to the New York Botanical Garden in 1937. It is a National Historic Landmark.',
  'A long stone mill on the river bank inside the Botanical Garden, restored in 2010, with a café and patio on the river side and a meeting room in the space that once held the snuff-grinding equipment. It is used for staff offices and catering, so the inside may be shut for events.',
  '',
  'Inside the New York Botanical Garden, which charges admission (garden page). Hours are the garden\'s, from its visit page; whether the mill itself is open on a given day was not checked.',
  [W('Lorillard Snuff Mill'),L('New York Botanical Garden: visit','https://www.nybg.org/visit/')],
  brick='no',hours='Garden: Tuesday to Sunday and Monday federal holidays 10 a.m. to 6 p.m.'),

N('bronx-borough-courthouse','Old Bronx Borough Courthouse','Bronx (Melrose)','nyc','civic','standing',40.82278,-73.91,'exact','view','walk','','1905–1914; empty since 1977',
  'A Beaux-Arts granite courthouse built from 1905 to 1914 at 161st Street and Third Avenue, with a statue of Justice by Jules Edouard Roiné over the entrance. It held the borough\'s courts until the Bronx County Courthouse opened in 1934, and a criminal court until 1977, when the city sealed it. Sold at auction in 1998, it has stood empty through several failed plans; in May 2024 it was offered for sale at $35 million.',
  'The four-story granite front facing south, with the figure of Justice between two columns over the door. The inside, described as having grand stairways and stained glass, is shut. A city landmark and on the National Register.',
  'Nearly fifty years sealed at one of the Bronx\'s busiest corners.',
  'Privately owned and closed. Look from East 161st Street, Third Avenue and Brook Avenue.',
  [W('Bronx Borough Courthouse'),L('Welcome2TheBronx: the courthouse for sale (May 2024)','https://www.welcome2thebronx.com/2024/05/another-bronx-landmark-for-sale-old-bronx-courthouse-on-the-market-for-35-million')],
  brick='no'),

N('kingsbridge-armory-bronx','Kingsbridge Armory (Eighth Regiment Armory)','Bronx (Kingsbridge Heights)','nyc','fort','standing',40.86791,-73.89856,'exact','view','walk','','1910s',
  'Built in the 1910s to designs by the state architect Lewis Pilcher for the National Guard regiment that moved here from Manhattan in 1917, and possibly the largest armory in the world. Besides drill it saw exhibitions, boxing and film work. The military left in 1996 and it has stood mostly empty since; after an ice-rink plan fell through, a redevelopment by 8th Regiment Partners was approved by the City Council in October 2025.',
  'A huge red-brick drill hall with a curved, sloping metal roof, its brickwork counted among the city\'s finest, with the regiment\'s shield and eagle in terra cotta over the entrance. The inside is not open.',
  '',
  'City-owned and closed while redevelopment is planned. Look from West Kingsbridge Road and Jerome Avenue (the 4 train stops at Kingsbridge Road).',
  [W('Kingsbridge Armory'),L('Governor\'s office: Kingsbridge Armory plan approved (October 2025)','https://www.governor.ny.gov/news/governor-hochul-mayor-adams-bronx-borough-president-gibson-nycedc-8th-regiment-partners-and')],
  brick='yes'),

N('st-anns-church-morrisania','St. Ann\'s Church of Morrisania','Bronx (Mott Haven)','nyc','worship','standing',40.80833,-73.9175,'site','view','walk','','1840–1841',
  'An Episcopal church that Gouverneur Morris Jr. built in 1840 as a memorial to his mother, Ann Cary Randolph Morris. It is a fieldstone Gothic Revival church with a Greek Revival tower. The graveyard and the Morris family crypt hold Gouverneur Morris, who helped write the Constitution, and Lewis Morris, a signer of the Declaration of Independence.',
  'The stone church with its tower, the 1916 stone parish house, a late-19th-century Sunday school building and the graveyard. Interior not checked; no service times were found on a page of the parish\'s own.',
  'A signer of the Declaration and the man who wrote the Constitution\'s preamble, buried in the South Bronx.',
  'An active Episcopal parish on St. Ann\'s Avenue. Look from the street; the parish runs an after-school program (Episcopal Diocese asset map).',
  [W('St. Ann\'s Episcopal Church (Bronx)'),L('Episcopal asset map: St. Ann\'s after-school program','https://www.episcopalassetmap.org/node/395')],
  brick='no',hours='?'),

N('st-peters-church-westchester-square','St. Peter\'s Church, Chapel and Cemetery','Bronx (Westchester Square)','nyc','worship','standing',40.83806,-73.84472,'site','view','walk','','1853–1855; rebuilt 1878',
  'An Episcopal church built in 1853 to designs by Leopold Eidlitz in what was then the village of Westchester, rebuilt by his son Cyrus after a heavy fire in 1878. The graveyard is older than the church and holds burials of the Dutch settlement of Oostdorp, and a stone for two unknown soldiers thought to have died in the Battle of Throgs Neck in October 1776.',
  'A cruciform church of rock-faced schist with a square corner tower and an eight-sided belfry, the chapel (used by the Bronx Academy of Arts and Dance since 2013) and the old graveyard. Interior not checked.',
  '',
  'Active Episcopal parish at 2500 Westchester Avenue. Look from Westchester Avenue and St. Peter\'s Avenue; service times were not found on a page of the parish\'s own.',
  [W('St. Peter\'s Church, Chapel and Cemetery Complex')],
  brick='no',hours='?'),

N('grace-church-city-island','Grace Episcopal Church, City Island','Bronx (City Island)','nyc','worship','standing',40.84111,-73.78403,'exact','open','walk','','1862',
  'A Carpenter Gothic wooden church built in 1862 on City Island\'s main street, with an Italian Villa rectory of about the same years. It was added to the National Register in 2006.',
  'The small wooden church and its rectory at 116 City Island Avenue. Interior not checked; anyone may come to the Sunday service (parish page).',
  '',
  'Active Episcopal parish. Street parking on City Island Avenue. Service time from the parish\'s own page.',
  [W('Grace Episcopal Church (Bronx)'),L('Grace Church City Island','https://www.gracecityisland.net/')],
  brick='no',hours='Sunday Eucharist 10 a.m.'),

N('hall-of-fame-great-americans','Hall of Fame for Great Americans','Bronx (University Heights)','nyc','curio','standing',40.85881,-73.91414,'site','open','walk','','1900–1901',
  'The first hall of fame in the United States: an open-air colonnade 630 feet long, designed by Stanford White for New York University\'s uptown campus and dedicated in 1901. It honours 102 Americans, 96 of them with bronze busts, and wraps round the Gould Memorial Library. It became part of Bronx Community College; the hall drew up to 50,000 visitors a year between the wars, far fewer later.',
  'The curving colonnade with its busts and plaques, behind the domed Gould Memorial Library. When read in November 2026 the college page said the hall was temporarily closed for construction.',
  'An American Valhalla almost nobody visits.',
  'Bronx Community College, 2155 University Avenue. Open when the college is open (college page); tours of the library are by arrangement. Temporarily closed for construction when read.',
  [W('Hall of Fame for Great Americans'),L('Bronx Community College: the Hall of Fame','https://www.bcc.cuny.edu/?p=63132')],
  conf='mixed',brick='?',hours='When the college is open: Monday to Friday 8 a.m. to 6 p.m., Saturday and Sunday 8 a.m. to 4 p.m. (closed for construction when read)'),

N('wave-hill-bronx','Wave Hill','Bronx (Riverdale)','nyc','inst','standing',40.89861,-73.91306,'site','open','walk','','1843',
  'A 28-acre estate above the Hudson. Wave Hill House was built in 1843 by William Lewis Morris as a grey fieldstone mansion and was enlarged by later owners. Theodore Roosevelt\'s family summered here in 1870 and 1871, Mark Twain leased it from 1901 to 1903 and Arturo Toscanini lived here in the 1940s. Given to the city in 1960, it is now a public garden and cultural center.',
  'Wave Hill House with Armor Hall, the stone wing an ichthyologist added as his private museum, and Glyndor House of 1927, now a gallery, set in gardens looking across the Hudson to the Palisades. Visitors can go into the house and gallery during opening hours (Wave Hill page).',
  'Mark Twain\'s summer rental, with the best view of the Palisades in the city.',
  'City-owned, run by Wave Hill, which charges admission. Entrance at West 249th Street and Independence Avenue; Wave Hill\'s own lot is east of the house and charges a fee. Hours from Wave Hill\'s visit page.',
  [W('Wave Hill'),L('Wave Hill: visit','https://www.wavehill.org/visit')],
  th=[40.89814,-73.91152],thn='Wave Hill parking, Independence Avenue',brick='no',
  hours='Tuesday to Sunday: grounds 10 a.m. to 4:30 p.m., Wave Hill House and gallery 10 a.m. to 4 p.m.'),

N('woodlawn-cemetery-bronx','Woodlawn Cemetery','Bronx (Woodlawn)','nyc','burial','standing',40.88917,-73.87333,'area','public','walk','','1863',
  'A rural-style cemetery of more than 400 acres opened in 1863, when this was still part of Yonkers. It holds more than 300,000 burials, among them Jay Gould, Robert Moses, Elizabeth Cady Stanton and Admiral Farragut, and family tombs by McKim, Mead & White, John Russell Pope, Cass Gilbert and others. A plaque on a high point near Gun Hill Road marks a redoubt the Continental Army built in 1776.',
  'Winding roads past grand family mausoleums, war memorials and the white marble soldiers\' stones in the north and south ends. A National Historic Landmark.',
  '',
  'Woodlawn Cemetery, privately run; its grounds are open to visitors (cemetery page). Entrances on Jerome Avenue and Webster Avenue; the Woodlawn station of the 4 train is by the Jerome Avenue gate. Grounds hours as the cemetery\'s visit page gives them for days the office is shut; other days not checked.',
  [W('Woodlawn Cemetery (Bronx)'),L('Woodlawn Cemetery: visit','https://www.woodlawn.org/visit/')],
  brick='?',hours='Grounds 8:30 a.m. to 4:30 p.m.'),

N('keepers-house-williamsbridge','Keeper\'s House at Williamsbridge Reservoir','Bronx (Norwood)','nyc','water','standing',40.87901,-73.87576,'exact','view','walk','','1889',
  'A stone house built in 1889 for the keeper of the Williamsbridge Reservoir, of granite blasted out when the reservoir was dug. The reservoir became the Williamsbridge Oval park in 1937. The Mosholu Preservation Corporation bought and restored the house in 1999 and uses it as its offices.',
  'An L-shaped granite house with a slate roof, clay ridge tiles and copper gutters, on the edge of the Oval. Offices, not open to the public.',
  '',
  'Owned by the Mosholu Preservation Corporation. Look from Reservoir Oval East; Williamsbridge Oval park is public.',
  [W('Keeper\'s House at Williamsbridge Reservoir')],
  brick='no'),

N('high-bridge-croton-bronx','High Bridge (Old Croton Aqueduct)','Bronx (Highbridge)','nyc','water','standing',40.8423,-73.9302,'site','public','walk','','1848',
  'The city\'s oldest major bridge, opened in 1848 to carry the Croton Aqueduct over the Harlem River 140 feet up. It had fifteen stone arches; the five over the river were replaced by one 450-foot steel arch in 1926 to 1928. Water stopped in 1958, the bridge was shut by the early 1970s, and after a restoration it reopened to people on foot and bicycles on June 9, 2015.',
  'The stone arches on the Bronx side and the steel river arch, with a restored herringbone brick walkway, Victorian-style lamps and the old water pipes still under the deck. The Manhattan end rises to the High Bridge Water Tower.',
  '',
  'NYC Parks. The Bronx end is near University Avenue and West 170th Street; the Manhattan end is in Highbridge Park at Amsterdam Avenue and 172nd Street. Hours not checked.',
  [W('High Bridge (New York City)')],
  brick='?'),

N('north-brother-island','North Brother Island (Riverside Hospital ruins)','Bronx (East River)','nyc','inst','ruins',40.80153,-73.8981,'area','view','walk','','1885–1943',
  'A 20-acre island in the East River where the city\'s Riverside Hospital for quarantined diseases moved in the mid-1880s; its last building, a tuberculosis pavilion, opened in 1943. Typhoid Mary was held here for over two decades until she died in 1938, and the steamer General Slocum burned and beached on its shore in 1904 with 1,021 dead. It was used for housing after the Second World War and for a center treating young drug users from the 1950s, then abandoned. The city now keeps it as a bird sanctuary.',
  'Most of the 25 hospital buildings still stand in the trees, in extreme decay. They can be seen only across the water: Barretto Point Park and the Tiffany Street Pier in Hunts Point look out on the island.',
  'The quarantine island, seen from the shore and nowhere closer.',
  'NYC Parks bird sanctuary. Landing is not allowed (NYC Parks page): escorted visits are given only to researchers and journalists. Look from Barretto Point Park (Viele Avenue at Tiffany Street) or the Tiffany Street Pier; the pin is the island, the parking point is the park.',
  [W('North and South Brother Islands (New York City)'),L('NYC Parks: North Brother Island','https://www.nycgovparks.org/parks/X308'),W('Barretto Point Park')],
  th=[40.8056,-73.8883],thn='Barretto Point Park (view point)',brick='?'),

N('fonthill-castle-bronx','Fonthill Castle','Bronx (Riverdale)','nyc','landmark','standing',40.91361,-73.90944,'exact','view','walk','','1852',
  'A small castle of six eight-sided towers in hammered grey stone, built in 1852 as the country house of the Shakespearean actor Edwin Forrest and his wife, the actress Catherine Sinclair, and named for Fonthill Abbey in England. Forrest sold it to the Sisters of Charity, who moved their academy here from the site of Central Park; it has been a convent, chapel, museum, library and admissions office of the College of Mount Saint Vincent.',
  'Five towers cluster round a three-story central one on the slope above the Hudson. The college\'s red-brick Administration Building beside it is on the same Register listing. Interior not checked.',
  'An actor\'s Gothic castle that became a college office.',
  'College of Mount Saint Vincent campus, private. Whether visitors may walk on the campus was not checked: treat it as view only.',
  [W('Fonthill Castle and the Administration Building of the College of Mount St. Vincent')],
  brick='no'),

N('nywb-180th-street-station','New York, Westchester and Boston Railway station, East 180th Street','Bronx (West Farms)','nyc','rail','standing',40.841,-73.874,'exact','public','walk','','1912',
  'The main station house of the New York, Westchester and Boston Railway, an electric commuter line that opened in 1912 to White Plains and Port Chester and went bankrupt in 1937. Designed by Fellheimer & Long, the building also held the railway\'s offices. Part of the line became the Dyre Avenue subway line; the old platforms were given up in 1957, but the station house is still the main entrance to the East 180th Street subway station, restored from 2010 to 2013.',
  'The railway\'s white, towered station house at East 180th Street and Morris Park Avenue, used every day as the subway station\'s entrance. Interior details not checked.',
  'A bankrupt railroad\'s grand station, still the way into the subway.',
  'MTA subway station, open to anyone with a fare for the platforms; the station house is the entrance.',
  [W('East 180th Street station')],
  brick='no'),

N('seton-hospital-grotto','Seton Hospital ruins and grotto, Seton Park and Raoul Wallenberg Forest','Bronx (Spuyten Duyvil)','nyc','inst','ruins',40.88731,-73.91781,'site','public','walk','','1895–1955',
  'Seton Hospital, a tuberculosis hospital opened in 1895 by the Sisters of Charity, stood here until the city closed it in 1955 and pulled it down in 1956. The land became Seton Park, opened in the mid-1970s, and the wooded Raoul Wallenberg Forest beside it. A small stone grotto that stood by the hospital was left in place, and in 2021 the Sisters of Charity said they hoped to restore it.',
  'NYC Parks\' trail map of Raoul Wallenberg Forest marks "Ruins of Seton Hospital" in the woods by the Orange Trail, where the pin is; what stands there is not described in any source read. The grotto, a small rock cave, is tucked behind the Seton Park tennis courts; in 2021 it was vandalized and littered (Riverdale Press).',
  'The last scrap of a tuberculosis hospital, behind the tennis courts.',
  'Seton Park and Raoul Wallenberg Forest, NYC Parks, off West 232nd Street and Independence Avenue; follow the Orange Trail into the forest. Park hours not checked.',
  [L('NYC Parks: Seton Park history','https://www.nycgovparks.org/parks/X201/history'),L('NYC Parks: Raoul Wallenberg Forest trail map','https://www.nycgovparks.org/pagefiles/166/Raoul-Wallenberg-Trail-Guide__60b6907af022b.pdf'),L('Riverdale Press: the grotto behind the tennis courts (2021)','https://riverdalepress.com/stories/treasure-hidden-behind-seton-park-tennis-courts,75585')],
  brick='no'),

N('van-cortlandt-station-putnam','Van Cortlandt Park station ruins (Putnam Division)','Bronx (Van Cortlandt Park)','nyc','rail','ruins',40.88895,-73.89382,'site','public','walk','','railroad 1869–1980; passenger service ended 1958',
  'A station on the "Old Put", the New York and Putnam line chartered in 1869 that ran from the Bronx to Brewster. Passenger trains last ran on May 29, 1958, and the last freight in 1980. The roadbed through Van Cortlandt Park is now the Putnam Trail.',
  'A clearing on the trail just beyond the lake bridge, past the golf clubhouse, with a row of columns, scattered stone and a few railroad ties showing in the ground (NYC Parks, 2006); a photograph on Wikimedia Commons shows the columns as the rusted steel frame of a platform shelter beside the trail. An overpass just south is dated 1909.',
  '',
  'Van Cortlandt Park, NYC Parks. Walk north on the Putnam Trail from the golf clubhouse area off Van Cortlandt Park South; the mapped park lot on Van Cortlandt Avenue West is close by. Hours not checked.',
  [L('NYC Parks: remnants of railroad history in Van Cortlandt Park (2006)','https://prd2.nycgovparks.org/parks/VanCortlandtPark/dailyplant/19768'),L('Forgotten New York: the Putnam Trail','https://forgotten-ny.com/2014/02/the-putnam-trail-riverdale/')],
  th=[40.88849,-73.89345],thn='Van Cortlandt Park lot, Van Cortlandt Avenue West',brick='?'),

N('rainey-memorial-gates','Rainey Memorial Gates, Bronx Zoo','Bronx (Bronx Park)','nyc','curio','standing',40.855,-73.87778,'site','view','walk','','1926–1934',
  'Bronze Art Deco gates by the sculptor Paul Manship, begun in 1926 and finished in 1934, given by Grace Rainey Rogers in memory of her brother Paul Rainey, a big-game hunter. They stand at the north side of the Bronx Zoo and are a city landmark.',
  'Bronze gates worked with stylised animals and plants and a seated lion, with low bronze screens joining them to granite gatekeepers\' lodges.',
  '',
  'Bronx Zoo (Wildlife Conservation Society), on the north side of Bronx Park near Fordham Road. Seen from the zoo\'s north side; zoo hours not checked.',
  [W('Rainey Memorial Gates')],
  brick='no'),
]

